// THE GATE THAT SAYS WHEN A LESSON HAS NO WALK.
//
// The walk's tests are generated by a loop over `LESSON_WALKS`, so a lesson missing from that table
// gets no test at all and a suite stays green with nothing checking it. A source scan for `test(`
// can't see a loop, so this compares ids. "No walk" means any of: a lesson in `LESSONS` with no entry
// in the table, an entry with no lesson, a lesson file `lessons/index.ts` doesn't list, a stage whose
// gesture the runner can't drive, or a refused gesture pointing at a step or stage that isn't there.
// A walk entry's `keyAt` is held too: each entry must name a key stage the lesson has, and a key that
// stage's own shortcut lists, or the walk would press something the card never asked for.
//
// It also scans all the `*.walk.ts` files and the runner they share for a test taken out of the run,
// and fails when one of the files the walk is known to need has gone. Playwright exits 0 on a skipped
// test, so this catches it on every `npm test`, and `scripts/check-walk-report.sh` catches what a
// source scan can't, such as a skip reached through an alias, in the walk's CI job.
//
// It imports the lesson data and the table, and reads the walk files and the index as text. The walk
// files import Playwright, and a vitest gate can't load that.

import { readFileSync, readdirSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { DRIVABLE_GESTURES, LESSON_WALKS, REFUSED_SENTENCE } from '../../e2e-live/support/lessonWalks.ts';
import { ADD_OUTPUT_LABEL } from '../chrome/PortsSection.tsx';
import { CLIENT_REFUSAL_COPY, REFUSAL_COPY } from '../chrome/RefusalMessage.tsx';
import { SHORTCUTS } from '../input/shortcuts.ts';
import { LESSONS } from '../tutorial/lessons/index.ts';
import { ADD_OUTPUT_WORDS } from '../tutorial/lessons/twoOutputs.ts';
import { MAX_NOTE_CHARS, REAL_TABLES, phrasePlain } from '../tutorial/phrase.ts';
import type { Lesson, LessonId, Stage } from '../tutorial/types.ts';
import { stripComments } from './walkSpecSource';

const LESSONS_DIR = new URL('../tutorial/lessons/', import.meta.url);
const E2E_LIVE_DIR = new URL('../../e2e-live/', import.meta.url);
const LESSON_WALK_FILE = 'e2e-live/lessons.walk.ts';
const WALK_RUNNER = 'e2e-live/support/lessonRunner.ts';
/** Each holds walk tests or the runner they share. A test count can't say which of these went missing. */
const NEEDED_WALK_FILES = [
  'e2e-live/lesson-entry.walk.ts',
  'e2e-live/lesson-hints.walk.ts',
  'e2e-live/lesson-variants.walk.ts',
  LESSON_WALK_FILE,
  'e2e-live/parity.walk.ts',
  WALK_RUNNER,
];

export interface CoverageArgs {
  lessons: readonly Lesson[];
  walks: Readonly<Record<string, unknown>>;
  drivable: readonly string[];
  /** The names in the `lessons/` directory. */
  lessonFiles: readonly string[];
  indexSource: string;
  /** Every `*.walk.ts` file and the shared runner, by path from `frontend/`. */
  walkFiles: Readonly<Record<string, string>>;
}

const LOOPS_OVER_TABLE = /\bfor\s*\(\s*const\s+\w+\s+of\s+Object\.keys\(\s*LESSON_WALKS\s*\)\s*\)/;
const SILENCED = /\b(?:test(?:\.describe|\.step)?|test\.info\(\)|testInfo)\.(?:skip|only|fixme|fail)\b/g;

function escapeForRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function auditFiles(args: CoverageArgs): string[] {
  const index = stripComments(args.indexSource);
  const listed = /\bLESSONS\b[^=]*=\s*\[([^\]]*)\]/.exec(index)?.[1] ?? '';
  return args.lessonFiles
    .filter((file) => /\.tsx?$/.test(file) && file !== 'index.ts' && !/\.test\.tsx?$/.test(file))
    .flatMap((file) => {
      const base = escapeForRegExp(file.replace(/\.tsx?$/, ''));
      const imported = new RegExp(`import\\s*\\{([^}]*)\\}\\s*from\\s*['"]\\./${base}(?:\\.tsx?)?['"]`).exec(index);
      if (imported === null) return [`${file}: lessons/index.ts doesn't import this file, so LESSONS can't hold its lesson`];
      const names = (imported[1] as string).split(',').map((n) => n.trim()).filter((n) => n !== '');
      const inTheList = names.some((n) => new RegExp(`\\b${escapeForRegExp(n)}\\b`).test(listed));
      return inTheList ? [] : [`${file}: lessons/index.ts imports this file and leaves it out of LESSONS`];
    });
}

function auditStage(stepLabel: string, stage: Stage, drivable: readonly string[]): string[] {
  const label = `${stepLabel} stage ${stage.id}`;
  const out: string[] = [];
  if (!drivable.includes(stage.gesture.do)) out.push(`${label}: the runner can't drive the gesture ${stage.gesture.do}`);
  if (stage.gesture.do === 'pressHint' && stage.hint === null) out.push(`${label}: this stage names a press and has no hint to press`);
  if (stage.gesture.do === 'dragHint' && (stage.hint?.on !== 'port' || stage.hint.to === undefined)) {
    out.push(`${label}: this stage names a drag and has no pair of ports to drag between`);
  }
  if (stage.gesture.do === 'dragToHint' && (stage.hint?.on !== 'port' || stage.hint.to !== undefined)) {
    out.push(`${label}: this stage names a drag into one ring and doesn't mark exactly one port`);
  }
  // The walk types where the ring marks, so a typing stage has to mark the code line.
  if (stage.gesture.do === 'typeCode' && (stage.hint?.on !== 'panel' || stage.hint.target.kind !== 'codeLine')) {
    out.push(`${label}: this stage types code and doesn't mark a code line`);
  }
  return out;
}

function auditRefused(lesson: Lesson): string[] {
  const step = lesson.steps.find((s) => s.id === lesson.refused.atStep);
  if (step === undefined) return [`${lesson.id}: its refused gesture names the step ${lesson.refused.atStep}, which this lesson doesn't have`];
  if (step.stages.some((s) => s.id === lesson.refused.atStage)) return [];
  return [`${lesson.id}: its refused gesture names the stage ${lesson.refused.atStage}, which step ${step.id} doesn't have`];
}

/** The walk entry's chosen keys, each against the stage it names and that stage's own shortcut. */
function auditKeyAt(lesson: Lesson, walk: unknown): string[] {
  const keyAt = (walk as { keyAt?: Readonly<Record<string, string>> } | undefined)?.keyAt ?? {};
  return Object.entries(keyAt).flatMap(([entry, key]) => {
    const [stepId, stageId] = entry.split('/');
    const stage = lesson.steps.find((s) => s.id === stepId)?.stages.find((s) => s.id === stageId);
    const label = `${lesson.id}: keyAt ${entry}`;
    if (stage === undefined) return [`${label} names a stage this lesson doesn't have`];
    if (stage.gesture.do !== 'key') return [`${label} names a stage whose gesture is ${stage.gesture.do}, not a key`];
    const keys: readonly string[] = SHORTCUTS[stage.gesture.shortcut].keys;
    if (!keys.includes(key)) return [`${label} chooses ${JSON.stringify(key)}, and the ${stage.gesture.shortcut} shortcut lists only ${keys.join(', ')}`];
    return [];
  });
}

/** One string per gap, each naming the lesson or file. Empty means every lesson gets a walk it can finish. */
export function auditLessonCoverage(args: CoverageArgs): string[] {
  const findings: string[] = [];
  const ids = new Set<string>(args.lessons.map((l) => l.id));
  for (const lesson of args.lessons) {
    if (!(lesson.id in args.walks)) findings.push(`${lesson.id}: this lesson has no entry in LESSON_WALKS, so it gets no walk test`);
    lesson.steps.forEach((step, i) => {
      for (const stage of step.stages) {
        findings.push(...auditStage(`${lesson.id} step ${i + 1} (${step.id})`, stage, args.drivable));
      }
    });
    findings.push(...auditRefused(lesson));
    findings.push(...auditKeyAt(lesson, args.walks[lesson.id]));
  }
  for (const id of Object.keys(args.walks)) {
    if (!ids.has(id)) findings.push(`${id}: LESSON_WALKS has an entry for this id, and LESSONS holds no such lesson`);
  }
  findings.push(...auditFiles(args));
  const walk = stripComments(args.walkFiles[LESSON_WALK_FILE] ?? '');
  if (!LOOPS_OVER_TABLE.test(walk)) findings.push('lessons.walk.ts: the file no longer loops over LESSON_WALKS, so a lesson may get no test');
  for (const needed of NEEDED_WALK_FILES) {
    if (!(needed in args.walkFiles)) findings.push(`${needed}: this file is gone, and the walk's tests or its runner went with it`);
  }
  for (const [path, source] of Object.entries(args.walkFiles)) {
    const stripped = stripComments(source);
    for (const m of stripped.matchAll(SILENCED)) {
      const line = stripped.slice(0, m.index).split('\n').length;
      findings.push(`${path}:${line}: holds ${m[0]}, which takes a test out of the walk's run`);
    }
  }
  return findings;
}

/**
 * The refusal tags lesson data names, each checked against the app's own tables. Lesson data keys its
 * coaching lines by plain strings, because `src/tutorial/` can't import the transport's tag type, so a
 * misspelt key would never match a refusal and the card would quietly fall back to the band's sentence.
 * Takes the tables as arguments, so its mutation cases run without touching the real tree.
 */
export function auditRefusalTags(
  lessons: readonly Lesson[],
  hostCopy: Readonly<Record<string, string>>,
  clientCopy: Readonly<Record<string, string>>,
): string[] {
  const known = (tag: string): boolean => Object.hasOwn(hostCopy, tag) || Object.hasOwn(clientCopy, tag);
  const findings: string[] = [];
  for (const lesson of lessons) {
    for (const step of lesson.steps) {
      for (const stage of step.stages) {
        for (const key of Object.keys(stage.coach ?? {})) {
          if (!known(key)) findings.push(`${lesson.id} step ${step.id} stage ${stage.id}: its coaching line is keyed ${key}, which is no refusal tag the app has`);
        }
      }
    }
    if (!known(lesson.refused.tag)) {
      findings.push(`${lesson.id} step ${lesson.refused.atStep} stage ${lesson.refused.atStage}: its refused gesture names the tag ${lesson.refused.tag}, which is no refusal tag the app has`);
    }
  }
  return findings;
}

/**
 * The card words each walk expects for its lesson's refused gesture, checked against what the lesson
 * data and the app's tables give: the refused stage's coaching line for the tag, or the band's own
 * sentence with no line. The walk reads the transcription, so this is what keeps it from drifting.
 */
export function auditRefusedCardNotes(
  lessons: readonly Lesson[],
  walks: Readonly<Record<string, { refusedCardNote: string } | undefined>>,
  hostCopy: Readonly<Record<string, string>>,
  clientCopy: Readonly<Record<string, string>>,
): string[] {
  const findings: string[] = [];
  for (const lesson of lessons) {
    const walk = walks[lesson.id];
    if (walk === undefined) continue;
    const { atStep, atStage, tag } = lesson.refused;
    const stage = lesson.steps.find((s) => s.id === atStep)?.stages.find((s) => s.id === atStage);
    const line = stage?.coach !== undefined && Object.hasOwn(stage.coach, tag) ? stage.coach[tag] : undefined;
    const band = Object.hasOwn(hostCopy, tag) ? hostCopy[tag] : Object.hasOwn(clientCopy, tag) ? clientCopy[tag] : undefined;
    const expected = line === undefined ? band : phrasePlain(line, REAL_TABLES);
    if (walk.refusedCardNote !== expected) {
      findings.push(`${lesson.id}: the walk expects the card to say "${walk.refusedCardNote}" for the refused gesture, and the lesson data gives "${expected ?? '(nothing)'}"`);
    }
  }
  return findings;
}

/** The same files Playwright's `testMatch` finds under `e2e-live/`, at any depth, plus the runner. */
function readWalkFiles(): Record<string, string> {
  const names = readdirSync(E2E_LIVE_DIR, { recursive: true, encoding: 'utf8' }).map((name) => name.split('\\').join('/'));
  const paths = names.map((name) => `e2e-live/${name}`).filter((path) => /\.walk\.ts$/.test(path) || path === WALK_RUNNER);
  return Object.fromEntries(paths.map((path) => [path, readFileSync(new URL(`../../${path}`, import.meta.url), 'utf8')]));
}

const REAL: CoverageArgs = {
  lessons: LESSONS,
  walks: LESSON_WALKS,
  drivable: DRIVABLE_GESTURES,
  lessonFiles: readdirSync(LESSONS_DIR),
  indexSource: readFileSync(new URL('index.ts', LESSONS_DIR), 'utf8'),
  walkFiles: readWalkFiles(),
};
const FIRST = LESSONS[0] as Lesson;

function withStage(change: (stage: Stage) => Stage): Lesson {
  const [step, ...rest] = FIRST.steps;
  const [stage, ...stages] = step!.stages;
  return { ...FIRST, steps: [{ ...step!, stages: [change(stage!), ...stages] }, ...rest] };
}

const audit = (change: Partial<CoverageArgs>): string => auditLessonCoverage({ ...REAL, ...change }).join('\n');
/** The real walk files with `text` added to the end of one. */
const withAdded = (path: string, text: string): CoverageArgs['walkFiles'] => ({ ...REAL.walkFiles, [path]: `${REAL.walkFiles[path] ?? ''}\n${text}` });
const withLessonWalk = (source: string): CoverageArgs['walkFiles'] => ({ ...REAL.walkFiles, [LESSON_WALK_FILE]: source });

describe('every lesson has a walk', () => {
  it('reads the real lessons, the real table and the real walk file', () => {
    expect(LESSONS.length).toBeGreaterThan(0);
    expect(REAL.lessonFiles).toContain('yourFirstLine.ts');
    expect(REAL.indexSource).toContain('YOUR_FIRST_LINE');
    expect(REAL.walkFiles[LESSON_WALK_FILE]).toContain('walkLesson');
    expect(REAL.walkFiles['e2e-live/parity.walk.ts']).toContain('test(');
    expect(REAL.walkFiles[WALK_RUNNER]).toContain('export async function walkLesson');
    expect(Object.keys(REAL.walkFiles).filter((path) => path.endsWith('.spec.ts')), 'the scan stays on the walk').toEqual([]);
  });

  it('holds one walk table entry per lesson', () => {
    expect(Object.keys(LESSON_WALKS).length).toBe(LESSONS.length);
  });

  it('lets the runner drive the seven gestures', () => {
    expect([...DRIVABLE_GESTURES].sort().join(' ')).toBe('dragHint dragToHint key none pressHint typeCode watch');
  });

  it("holds the app's own sentence for the refusal the walk reads", () => {
    expect(REFUSED_SENTENCE).toBe(REFUSAL_COPY.FootprintCollision);
  });

  it("holds lesson 4's typed + Add output to the button's own label", () => {
    expect(ADD_OUTPUT_WORDS).toBe(ADD_OUTPUT_LABEL);
    const step = LESSONS.flatMap((l) => l.steps).find((s) => s.id === 'add-output');
    const words = step?.stages.flatMap((stage) => stage.text.filter((t): t is string => typeof t === 'string')).join('') ?? '';
    expect(words, 'the add-output stage says the label it marks').toContain(ADD_OUTPUT_LABEL);
  });

  it('finds nothing in the real tree', () => {
    expect(auditLessonCoverage(REAL)).toEqual([]);
  });

  it("holds the card words each walk expects for its refused gesture to the lesson's own", () => {
    expect(auditRefusedCardNotes(LESSONS, LESSON_WALKS, REFUSAL_COPY, CLIENT_REFUSAL_COPY)).toEqual([]);
  });

  it("keys every coaching line and refused gesture by one of the app's refusal tags", () => {
    expect(auditRefusalTags(LESSONS, REFUSAL_COPY, CLIENT_REFUSAL_COPY)).toEqual([]);
  });

  it(`holds every band sentence to the card's ${MAX_NOTE_CHARS}-character note budget, since a tag with no lesson line shows it there`, () => {
    const sentences = Object.entries({ ...REFUSAL_COPY, ...CLIENT_REFUSAL_COPY });
    expect(sentences.length).toBe(Object.keys(REFUSAL_COPY).length + Object.keys(CLIENT_REFUSAL_COPY).length);
    for (const [tag, sentence] of sentences) {
      expect(sentence.length, `${tag}: "${sentence}"`).toBeLessThanOrEqual(MAX_NOTE_CHARS);
    }
  });

  describe('fails on', () => {
    it('a lesson with no walk entry', () => {
      const second: Lesson = { ...FIRST, id: 'a-second-lesson' as LessonId };
      expect(audit({ lessons: [...LESSONS, second] })).toMatch(/a-second-lesson: this lesson has no entry in LESSON_WALKS/);
    });

    it('a walk entry with no lesson', () => {
      expect(audit({ walks: { ...LESSON_WALKS, 'a-gone-lesson': {} } })).toMatch(/a-gone-lesson: LESSON_WALKS has an entry/);
    });

    it('a file under lessons/ that index.ts does not import', () => {
      expect(audit({ lessonFiles: [...REAL.lessonFiles, 'aSecondLesson.ts'] })).toMatch(/aSecondLesson\.ts: lessons\/index\.ts doesn't import/);
    });

    it('a file under lessons/ that index.ts imports and leaves out of LESSONS', () => {
      const indexSource = REAL.indexSource.replace('[YOUR_FIRST_LINE, DELETE_AND_UNDO, TWO_OUTPUTS]', '[DELETE_AND_UNDO, TWO_OUTPUTS]');
      expect(indexSource, 'the substitution landed').not.toBe(REAL.indexSource);
      expect(audit({ indexSource })).toMatch(/yourFirstLine\.ts: lessons\/index\.ts imports this file and leaves it out/);
    });

    it('a stage whose gesture is not drivable', () => {
      const lesson = withStage((s) => ({ ...s, gesture: { do: 'hover' } as unknown as Stage['gesture'] }));
      expect(audit({ lessons: [lesson] })).toMatch(/your-first-line step 1 \(place-source\) stage board-paused: the runner can't drive the gesture hover/);
    });

    it('a press stage with a null hint', () => {
      const lesson = withStage((s) => ({ ...s, gesture: { do: 'pressHint' }, hint: null }));
      expect(audit({ lessons: [lesson] })).toMatch(/your-first-line step 1 \(place-source\) stage board-paused: this stage names a press and has no hint/);
    });

    it('a drag stage with no pair of ports', () => {
      const lesson = withStage((s) => ({ ...s, gesture: { do: 'dragHint' }, hint: { on: 'port', of: 'source', role: 'out' } }));
      expect(audit({ lessons: [lesson] })).toMatch(/stage board-paused: this stage names a drag and has no pair of ports/);
    });

    it('a drag into one ring that marks a pair of ports', () => {
      const lesson = withStage((s) => ({ ...s, gesture: { do: 'dragToHint' }, hint: { on: 'port', of: 'source', role: 'out', to: { of: 'sink', role: 'in' } } }));
      expect(audit({ lessons: [lesson] })).toMatch(/stage board-paused: this stage names a drag into one ring and doesn't mark exactly one port/);
    });

    it('a typeCode stage that marks no code line', () => {
      const typing = { do: 'typeCode', after: 'a', insert: 'b' } as const;
      const onApply = withStage((s) => ({ ...s, gesture: typing, hint: { on: 'panel', target: { kind: 'applyButton' } } }));
      expect(audit({ lessons: [onApply] })).toMatch(/stage board-paused: this stage types code and doesn't mark a code line/);
      const onTheFloor = withStage((s) => ({ ...s, gesture: typing, hint: { on: 'machine', of: 'source' } }));
      expect(audit({ lessons: [onTheFloor] })).toMatch(/this stage types code and doesn't mark a code line/);
      const onTheLine = withStage((s) => ({ ...s, gesture: typing, hint: { on: 'panel', target: { kind: 'codeLine', holds: 'a' } } }));
      expect(audit({ lessons: [onTheLine] }), 'marking the code line is clean').not.toMatch(/types code/);
    });

    it('a drag into one ring that marks no port', () => {
      const lesson = withStage((s) => ({ ...s, gesture: { do: 'dragToHint' } }));
      expect(audit({ lessons: [lesson] })).toMatch(/stage board-paused: this stage names a drag into one ring and doesn't mark exactly one port/);
    });

    describe('a keyAt entry', () => {
      const DU = 'delete-and-undo';
      const withKeyAt = (keyAt: Record<string, string>): CoverageArgs['walks'] => ({
        ...LESSON_WALKS,
        [DU]: { ...LESSON_WALKS[DU], keyAt },
      });

      it('holds the real entry, which picks Delete and Backspace', () => {
        expect(LESSON_WALKS[DU].keyAt).toEqual({ 'delete-belt/press-delete': 'Delete', 'delete-sink/press-delete': 'Backspace' });
      });

      it('naming a stage the lesson lacks', () => {
        expect(audit({ walks: withKeyAt({ 'delete-belt/no-such-stage': 'Delete' }) })).toContain(`${DU}: keyAt delete-belt/no-such-stage names a stage this lesson doesn't have`);
      });

      it('naming a stage whose gesture is not a key', () => {
        expect(audit({ walks: withKeyAt({ 'delete-belt/select-belt': 'Delete' }) })).toContain(`${DU}: keyAt delete-belt/select-belt names a stage whose gesture is pressHint, not a key`);
      });

      it("choosing a key the stage's shortcut doesn't list", () => {
        expect(audit({ walks: withKeyAt({ 'delete-sink/press-delete': 'x' }) })).toContain(`${DU}: keyAt delete-sink/press-delete chooses "x", and the delete shortcut lists only Delete, Backspace`);
      });
    });

    it('a refused step that does not exist', () => {
      const lesson: Lesson = { ...FIRST, refused: { ...FIRST.refused, atStep: 'no-such-step' } };
      expect(audit({ lessons: [lesson] })).toMatch(/your-first-line: its refused gesture names the step no-such-step/);
    });

    it('a refused stage that does not exist', () => {
      const lesson: Lesson = { ...FIRST, refused: { ...FIRST.refused, atStage: 'no-such-stage' } };
      expect(audit({ lessons: [lesson] })).toMatch(/your-first-line: its refused gesture names the stage no-such-stage/);
    });

    it('a coaching line keyed by a misspelt tag', () => {
      const lesson = withStage((s) => ({ ...s, coach: { FootprintColision: ['That cell is taken.'] } }));
      expect(auditRefusalTags([lesson], REFUSAL_COPY, CLIENT_REFUSAL_COPY).join('\n')).toMatch(
        /your-first-line step place-source stage board-paused: its coaching line is keyed FootprintColision, which is no refusal tag/,
      );
    });

    it("a coaching line deleted from the lesson the walk still expects", () => {
      const steps = FIRST.steps.map((step) => ({ ...step, stages: step.stages.map((stage) => ({ ...stage, coach: undefined })) }));
      expect(auditRefusedCardNotes([{ ...FIRST, steps }], LESSON_WALKS, REFUSAL_COPY, CLIENT_REFUSAL_COPY).join('\n')).toContain(
        `the lesson data gives "${REFUSAL_COPY.FootprintCollision}"`,
      );
    });

    it('a refused gesture naming a tag the app has none of', () => {
      const lesson: Lesson = { ...FIRST, refused: { ...FIRST.refused, tag: 'NoSuchRefusal' } };
      expect(auditRefusalTags([lesson], REFUSAL_COPY, CLIENT_REFUSAL_COPY).join('\n')).toMatch(
        /your-first-line step place-sink stage sink-floor: its refused gesture names the tag NoSuchRefusal/,
      );
    });

    it('a walk file that does not loop over LESSON_WALKS', () => {
      expect(audit({ walkFiles: withLessonWalk('for (const lesson of LESSONS) { test(lesson.id, () => {}); }') })).toMatch(/no longer loops over LESSON_WALKS/);
    });

    it('a walk file whose loop sits in a comment', () => {
      expect(audit({ walkFiles: withLessonWalk('// for (const id of Object.keys(LESSON_WALKS)) {}') })).toMatch(/no longer loops over LESSON_WALKS/);
    });

    it('each way of taking a test out of the run, in each walk file and the runner', () => {
      for (const path of NEEDED_WALK_FILES) {
        for (const form of ['test.skip', 'test.only', 'test.fixme', 'test.fail', 'test.describe.skip', 'test.describe.only', 'test.describe.fixme', 'test.step.skip', 'testInfo.skip', 'testInfo.fixme', 'test.info().skip', 'test.info().fail']) {
          const found = audit({ walkFiles: withAdded(path, `${form}('x', () => {});`) });
          expect(found, `${path}: ${form}`).toMatch(new RegExp(`^${path.replace(/\./g, '\\.')}:\\d+: holds ${form.replace(/[.()]/g, '\\$&')},`, 'm'));
        }
      }
    });

    it('a walk file nobody has listed yet', () => {
      const path = 'e2e-live/a-new-one.walk.ts';
      expect(audit({ walkFiles: withAdded(path, "test.skip('x', () => {});") })).toContain(`${path}:2: holds test.skip`);
    });

    it('each needed walk file going missing', () => {
      for (const path of NEEDED_WALK_FILES) {
        const walkFiles = Object.fromEntries(Object.entries(REAL.walkFiles).filter(([name]) => name !== path));
        expect(audit({ walkFiles }), path).toContain(`${path}: this file is gone`);
      }
    });
  });

  it('stays quiet on test.skip in a comment in a walk file', () => {
    for (const path of NEEDED_WALK_FILES) {
      expect(audit({ walkFiles: withAdded(path, "// test.skip('x', () => {});") }), path).toBe('');
    }
  });
});
